INSERT INTO feature VALUES('certificate-composition','rewriting','Certificate composition and pathway queries','derivation-identity','implemented','notable',NULL,'Certificates compose sequentially in two modes, and bounded backward queries find the pathways that produced a step. The directed gate reads each seam hole of the left join through the substitutions that the steps record, so a cell variable that only spells a hole''s name is no endpoint of that hole.','theory-decomposition-spaces','crates/theory-decomposition-spaces/tests/composition.rs crates/theory-decomposition-spaces/tests/pathway.rs',NULL,NULL);
